  handleCancelCustomEnemy = () => {
    this.setState({
      mode: 'SELECT_AI'
    })
  }

  handleCustomAiChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    this.setState({
      customAiCode: event.target.value
    })
  }

