  })
  .join('')
  .replace(/(....)/g, '$1 ')

/**
  Convert a string back into an array of moves
*/
const decode = (string: string): string[] => string
  .split('')
  .map((chr: string): string[] => reverseLookup[chr] ?? [])
  .flat()

export default { encode, decode }
